urlset:
{%- for file in pages -%}
  {% if file.page and not file.page.is_link and (file.page.abs_url or file.page.canonical_url) %}


      {% if file.page.canonical_url %}
        {{ file.page.canonical_url
             | replace('http://0.0.0.0:8080', 'https://docs.subscrypts.com')
             | replace('http://0.0.0.0:8083', 'https://docs.subscrypts.com')
             | replace('0.0.0.0:8080', 'docs.subscrypts.com')
             | replace('0.0.0.0:8083', 'docs.subscrypts.com')
             | e }}
      {% else %}
        {{ file.page.abs_url
             | replace('http://0.0.0.0:8080', 'https://docs.subscrypts.com')
             | replace('http://0.0.0.0:8083', 'https://docs.subscrypts.com')
             | replace('0.0.0.0:8080', 'docs.subscrypts.com')
             | replace('0.0.0.0:8083', 'docs.subscrypts.com')
             | e }}
      {% endif %}

    {% if file.page.update_date %}
    {{ file.page.update_date }}
    {% endif %}
    weekly

  {% endif %}
{%- endfor -%}
